package com.example.historyquizru.data

import androidx.room.RoomDatabase
import androidx.sqlite.db.SupportSQLiteDatabase

object DatabaseSeeder {
    val callback = object : RoomDatabase.Callback() {
        override fun onCreate(db: SupportSQLiteDatabase) {
            super.onCreate(db)
            seed(db)
        }
    }

    private data class SeedPersonality(
        val epochId: Int,
        val name: String,
        val years: String,
        val imageName: String,
        val hint: String,
        val description: String
    )

    private fun seed(db: SupportSQLiteDatabase) {
        val epochs = listOf(
            listOf(1, "Древняя Русь", "Русь от образования первых княжеств до объединения земель", 1),
            listOf(2, "Московское царство", "Московское государство и царская власть", 2),
            listOf(3, "Российская империя", "Россия от реформ Петра I до начала XX века", 3),
            listOf(4, "СССР", "История Советского Союза", 4),
            listOf(5, "Современная Россия", "Россия с конца XX века по настоящее время", 5)
        )

        epochs.forEach { epoch ->
            db.execSQL(
                "INSERT OR IGNORE INTO epochs (id, name, description, orderIndex) VALUES (?, ?, ?, ?)",
                arrayOf(epoch[0], epoch[1], epoch[2], epoch[3])
            )
        }

        val personalities = listOf(
            SeedPersonality(1, "Рюрик", "IX век", "ryurik.jpg", "Согласно летописи, призван на княжение в 862 году. Считается основателем династии Рюриковичей.", "Летописный основатель династии Рюриковичей. Единственным источником сведений о нём является «Повесть временных лет» и восходящая к ней летописная традиция. Согласно этому тексту, в 862 году был призван на княжение племенами словен, чуди, кривичей и веси вместе с братьями Синеусом и Трувором. Братья сели в Ладоге, Белоозере и Изборске; после их смерти Рюрик принял всю власть и, по одной из летописных версий, основал Новгород. Умер в 879 году, оставив малолетнего сына Игоря на попечение родича Олега. Историчность Рюрика и достоверность летописного сказания остаются предметом научной дискуссии; вопрос о его этническом происхождении также не решён. Сама дата 862 года была официально закреплена как «начальное событие российской государственности» указом императора Николая I в 1852 году, и с тех пор призвание варягов традиционно считается точкой отсчёта русской истории. Споры о том, кем были варяги — скандинавами, славянами или балтами — и имело ли место призвание в реальности, продолжаются в историографии уже более двух столетий."),
            SeedPersonality(1, "Олег Вещий", "ум. 912", "oleg_veshiy.jpg", "В 882 году объединил Новгород и Киев. Совершил поход на Константинополь и заключил договор с Византией в 911 году.", "Князь, правивший после Рюрика. Согласно «Повести временных лет», после смерти Рюрика в 879 году принял власть как опекун малолетнего Игоря. В 882 году захватил Киев, убив Аскольда и Дира, и перенёс туда столицу, объединив северные и южные земли. Подчинил древлян, северян и радимичей, освободив их от дани Хазарскому каганату. В 907 году совершил поход на Константинополь; по летописи, войско двигалось на ладьях, поставленных на колёса, а в знак победы Олег прибил свой щит на вратах города. Под 911 годом в летописи помещён договор с Византией, обеспечивавший русским купцам право беспошлинной торговли. Обстоятельства его смерти изложены в летописном предании о коне и змее, которое легло в основу известного стихотворения Пушкина. Прозвище «Вещий» (то есть знающий будущее, провидящий) закрепилось за ним в летописной традиции. Византийские источники, подробно описывающие аналогичные походы других народов, не упоминают поход 907 года, что даёт основание части историков считать его легендарным."),
            SeedPersonality(1, "Ольга", "ок. 920–969", "olga.jpg", "Правила Русью при малолетнем Святославе. Упорядочила сбор дани и приняла христианство в Константинополе.", "Княгиня, правившая после гибели мужа, князя Игоря, при малолетнем сыне Святославе. Согласно летописи, отомстила древлянам за смерть Игоря, уничтожив их столицу Искоростень, и провела упорядочение сбора дани, установив «уроки» (фиксированные размеры повинностей) и «погосты» (места сбора дани). В историографии эти меры получили название «реформ княгини Ольги», хотя их суть не вполне выяснена: распространённое представление об упразднении полюдья и организации сети погостов как пунктов своза дани оспаривается, поскольку этимология самого термина «погост» указывает на его происхождение из практики полюдья. Около 957 года (по византийским источникам; в «Повести временных лет» называется 955 год) совершила поездку в Константинополь, где приняла христианство под именем Елены. Состав русской делегации показывает, что Ольга имела в виду не только церковные вопросы, но и обновление торгово-политического договора 944 года. Впоследствии была причислена к лику святых; официальная канонизация как равноапостольной состоялась в 1595 году."),
            SeedPersonality(1, "Святослав Игоревич", "ок. 942–972", "svyatoslav.jpg", "Князь-воин, почти всё правление проведший в походах. Разгромил Хазарский каганат, воевал с Византией, погиб в бою с печенегами.", "Киевский князь, большую часть правления проведший в военных походах; внутренними делами государства при нём в значительной мере занималась мать, княгиня Ольга. Формально стал великим князем в трёхлетнем возрасте после гибели отца в 945 году, но самостоятельное правление началось около 964 года. В 964–966 годах подчинил вятичей, ранее плативших дань хазарам, и разгромил Хазарский каганат, разрушив Саркел на Дону и Итиль на Волге; на берегах Керченского пролива основал форпост русского влияния — будущую Тмутаракань. В 967 или 968 году вторгся в Дунайскую Болгарию и обосновался на Дунае, назвав город Малая Преслава Переяславцем и объявив его своей столицей. В ходе войны с Византией в 971 году после осады Доростола заключил мир с императором Иоанном Цимисхием. Погиб в 972 году у днепровских порогов в бою с печенегами, возвращаясь на Русь. Летопись характеризует его как неприхотливого в быту воина, который не возил с собой обозов и котлов, а мясо жарил на углях, и передаёт его знаменитую фразу-предупреждение: «Иду на вы»."),
            SeedPersonality(1, "Владимир Святославич", "ок. 960–1015", "vladimir_svyatoslavich.jpg", "Крестил Русь около 988 года. Принял христианство из Византии и женился на царевне Анне.", "Киевский князь, при котором произошло Крещение Руси. Сын Святослава и Малуши, княжил сначала в Новгороде, в 978 году захватил Киев, победив брата Ярополка. Около 988 года принял христианство из Византии и женился на царевне Анне. По летописи, крестился в Корсуне (Херсонесе) и был наречён Василием, а затем крестил киевлян и начал христианизацию Руси. Вернувшись в Киев, он привёз греческих священников и способствовал обращению в веру своих сыновей, бояр и местного населения, а позже и жителей других городов. Важнейшим следствием стало учреждение Русской митрополии Константинопольского патриархата и нескольких епархий; по приказу Владимира взамен уничтожавшихся языческих идолов развернулось строительство православных храмов. Вместе с христианством из Византии на Русь пришла грамотность, центрами распространения которой стали храмы и монастыри, где образовывались школы. Впоследствии был причислен к лику святых; в народной традиции получил прозвище «Красное Солнышко»."),
            SeedPersonality(1, "Ярослав Мудрый", "ок. 978–1054", "yaroslav_mudry.jpg", "При нём составлена «Русская Правда». Строил храмы и укреплял международные связи через династические браки.", "Киевский князь, при котором был составлен первый известный письменный свод законов Руси — «Русская Правда». Сын Владимира Святославича и полоцкой княжны Рогнеды, при распределении столов получил Ростов, а после смерти старшего брата Вышеслава перешёл в Новгород. По-видимому, уже в 1010-х годах в Новгороде произошла первая кодификация обычного древнерусского права — так называемая «Правда Ярослава», древнейшая часть «Русской Правды». После смерти отца в 1015 году начал борьбу со Святополком, выступив мстителем за убийство братьев Бориса и Глеба; занял Киев после победы у Любеча в 1016 году, но окончательно утвердился на престоле лишь в 1019 году после битвы на Альте. В 1020-е годы его правление осложнялось конфликтом с братом Мстиславом Тмутараканским, завершившимся разделом государства по Днепру; лишь после смерти Мстислава в 1035 году Ярослав стал «самовластцем» на Руси. В его правление (1019–1054) были построены Софийский собор в Киеве, Золотые ворота с надвратной церковью, основаны монастыри святых Георгия и Ирины; прообразами этих сооружений были постройки Константинополя и Иерусалима. Вёл активную внешнюю политику, укреплял международные связи через династические браки: был женат на дочери шведского конунга Ингигерде, а его дочери были замужем за королями Франции, Норвегии и Венгрии. Прозвище «Мудрый» закрепилось за ним в историографии."),
            SeedPersonality(1, "Владимир Мономах", "1053–1125", "vladimir_monomakh.jpg", "Киевский князь, инициатор Любечского съезда и автор «Поучения детям».", "Владимир Всеволодович Мономах родился в 1053 году в семье князя Всеволода Ярославича и «греческой царевны», предположительно дочери византийского императора Константина IX Мономаха, от которого получил прозвище. При жизни отца княжил в Ростове, Смоленске, Чернигове, а с 1094 года — в Переяславле. После смерти отца в 1093 году уступил киевский престол двоюродному брату Святополку Изяславичу, не желая междоусобицы. Был главным инициатором Любечского съезда князей 1097 года, на котором был провозглашён принцип «каждо да держит отчину свою». В 1113 году после смерти Святополка и восстания киевлян против ростовщиков был призван на киевский престол. Издал «Устав о резах», ограничивший произвол ростовщиков, который вошёл в состав «Русской Правды». Был вдохновителем и одним из руководителей совместных походов против половцев. Умер 19 мая 1125 года. Автор «Поучения детям» — литературного памятника, соединяющего нравственные наставления с автобиографическим рассказом о походах и трудах."),
            SeedPersonality(1, "Юрий Долгорукий", "ок. 1090–1157", "yuriy_dolgorukiy.jpg", "Ростово-суздальский и киевский князь, с именем которого связано первое упоминание Москвы.", "Юрий Владимирович Долгорукий — один из младших сыновей Владимира Мономаха. Точная дата рождения дискуссионна; современные исследователи относят её к концу 1090-х — 1100 году. После смерти отца в 1125 году стал князем ростово-суздальским и перенёс столицу княжества из Ростова в Суздаль. С начала 1130-х годов боролся за южные города Переяславль и Киев, за что получил прозвище Долгорукий. При нём были основаны города Переяславль-Залесский, Юрьев-Польский, Дмитров. В 1147 году в летописи впервые упомянута Москва — в связи с приглашением Юрием своего союзника, новгород-северского князя Святослава Ольговича. В 1155 году окончательно занял Киев, но правил недолго: умер в 1157 году, по-видимому, от отравления."),
            SeedPersonality(1, "Александр Невский", "1220–1263", "nevskiy__aliexand.jpg", "Новгородский и владимирский князь, победитель шведов на Неве и Ливонского ордена на Чудском озере.", "Александр Ярославич родился 30 мая 1220 года (по старой историографической традиции; современные исследователи называют 13 мая 1221 года) в семье князя Ярослава Всеволодовича и княгини Феодосии, внук Всеволода Большое Гнездо. В 1236 году был посажен на новгородское княжение. В июле 1240 года в возрасте 19 лет разбил шведский отряд в устье реки Ижоры, за что получил прозвище Невский. 5 апреля 1242 года на льду Чудского озера разгромил войско Ливонского ордена в битве, вошедшей в историю как Ледовое побоище. В отношениях с Золотой Ордой проводил политику компромисса, несколько раз ездил в Орду и добился освобождения русских от обязанности выступать в татарских войнах. В 1262 году, возвращаясь из Орды, где пытался умиротворить хана после восстаний против данников, заболел и умер в Городце. Был похоронен во Владимире; в 1547 году причислен к лику святых."),
            SeedPersonality(1, "Дмитрий Донской", "1350–1389", "dmitry_donskoy.jpg", "Московский князь, возглавивший русские войска в Куликовской битве 1380 года.", "Дмитрий Иванович родился 12 октября 1350 года в Москве, сын князя Ивана II Красного и внук Ивана Калиты. После смерти отца в 1359 году опекуном и наставником малолетнего князя стал митрополит Алексий. В 1367 году построил в Москве первый белокаменный Кремль. В 1368 и 1370 годах московские войска отразили нападения литовского князя Ольгерда. В 1375 году принудил тверского князя Михаила Александровича к признанию своего старшинства. В 1378 году на реке Воже разбил ордынское войско Бегича, а 8 сентября 1380 года в Куликовской битве на Дону разгромил войско Мамая, за что получил прозвище Донской. В 1382 году не смог предотвратить разорения Москвы Тохтамышем и был вынужден возобновить выплату дани Орде. В духовной грамоте впервые передал великое княжение своему сыну Василию без санкции хана. Умер 19 мая 1389 года, погребён в Архангельском соборе Кремля."),
            SeedPersonality(1, "Игорь Рюрикович", "ок. 878–945", "igor_ryurikovich.jpg", "Киевский князь, сын Рюрика, погибший при сборе дани с древлян.", "Игорь Рюрикович — сын Рюрика, по летописи княжил в Киеве с 912 года после смерти Олега, правившего при его малолетстве. В 914 году подавил восстание древлян и наложил на них дань, в 915 году впервые заключил мир с печенегами, появившимися в русских степях. Совершил два похода на Византию: в 941 году русский флот был сожжён греческим огнём, а в 944 году поход завершился мирным договором, текст которого сохранился в «Повести временных лет». В 945 году по требованию дружины, недовольной своим содержанием, отправился за данью к древлянам, произвольно увеличил её размер, а затем с малой частью дружины вернулся за дополнительной данью. Древляне возмутились и убили князя. По свидетельству византийского историка Льва Диакона, Игорь был привязан к верхушкам двух нагнутых деревьев и разорван надвое."),
            SeedPersonality(1, "Андрей Боголюбский", "ок. 1111–1174", "andrey_bogolyubsky.jpg", "Владимиро-суздальский князь, перенёсший столицу княжества во Владимир.", "Андрей Юрьевич Боголюбский родился между 1120 и 1125 годами, был сыном Юрия Долгорукого от первого брака с дочерью половецкого хана. В 1155 году вопреки воле отца покинул Вышгород и уехал в Суздальскую землю, увезя с собой вышгородскую икону Богородицы, ставшую впоследствии Владимирской иконой. После смерти Юрия Долгорукого в 1157 году занял ростово-суздальский стол и перенёс центр княжества из Ростова и Суздаля во Владимир-на-Клязьме. В 1169 году организовал поход на Киев, после чего «старейшинство» владимирского князя признали другие князья. Прозвище получил по названию своей резиденции Боголюбово под Владимиром. Был убит в ночь на 29 июня 1174 года в результате заговора, главную роль в котором сыграл боярский род Кучковичей."),
            SeedPersonality(1, "Всеволод Большое Гнездо", "1154–1212", "vsevolod_bolshoe_gnezdo.jpg", "Великий князь владимирский, при котором Владимиро-Суздальская земля достигла могущества.", "Всеволод Юрьевич родился 19 октября 1154 года, был младшим сыном Юрия Долгорукого от второго брака. В 1162 году вместе с матерью и братьями был изгнан старшим братом Андреем Боголюбским и уехал в Византию, где провёл несколько лет. Вернувшись на Русь, в 1176 году после смерти брата Михаила занял владимирский престол. В 1177 году разбил войско племянника Мстислава Ростиславича и рязанского князя Глеба на реке Колокше, укрепив свою власть. Прозвище «Большое Гнездо» получил за многодетность — у него было 12 детей, восемь сыновей и четыре дочери. Умер 15 апреля 1212 года во Владимире."),
            SeedPersonality(1, "Даниил Галицкий", "1201–1264", "daniil_galitsky.jpg", "Галицко-волынский князь, объединивший юго-западные земли и принявший королевский титул.", "Даниил Романович родился в 1201 году, был сыном галицко-волынского князя Романа Мстиславича. После гибели отца в 1205 году детство и юность прошли в борьбе за отцовское наследство с боярами и соседними князьями. В 1221 году стал княжить на Волыни, а в 1238 году окончательно овладел Галичем, завершив объединение галицких и волынских земель. В 1245 году в битве под Ярославлем разгромил войска венгров и поляков, завершив многолетнюю борьбу за восстановление единства княжества. В 1253 году был коронован папой римским как первый и единственный коронованный русский король, однако решительно противостоял попыткам распространения католического влияния. Основал города Холм, Львов, Данилов, перенёс столицу княжества в Холм. Умер в 1264 году."),
            SeedPersonality(1, "Сергий Радонежский", "ок. 1314–1392", "sergiy_radonezhskiy.jpg", "Основатель Троицкого монастыря, духовный наставник Дмитрия Донского.", "Сергий Радонежский, в миру Варфоломей, родился около 1314 года в семье ростовских бояр Кирилла и Марии. После смерти родителей вместе со старшим братом Стефаном удалился в лес на холме Маковец, где построил келью и церковь во имя Святой Троицы. Около 1337 года принял монашеский постриг с именем Сергий. К нему стали приходить иноки, и между 1353 и 1356 годами он стал игуменом возникшего Троицкого монастыря. В 1380 году благословил князя Дмитрия Ивановича и русское войско на битву с Мамаем, что придало сражению духовный характер. Его ученики основали до двадцати монастырей по всей Руси, за что Сергия называют «игуменом земли Русской». Умер 25 сентября 1392 года, канонизирован не позднее 1448 года."),
            SeedPersonality(1, "Митрополит Иларион", "XI век", "ilarion_metropolitan.jpg", "Первый русский митрополит, автор «Слова о законе и благодати».", "Иларион был священником придворной церкви святых Апостолов в Берестове под Киевом и пользовался расположением князя Ярослава Мудрого. В 1051 году был поставлен митрополитом Киевским и всея Руси собором русских епископов без согласования с Константинопольским патриархатом, что стало важным шагом к независимости русской церкви. Был автором первого дошедшего до нас оригинального памятника древнерусской литературы — торжественного «Слова о законе и благодати», в котором прославлял крещение Руси и князя Владимира. Оставил митрополичью кафедру, вероятно, после смерти Ярослава Мудрого в 1054 году; дальнейшие сведения о его жизни отрывочны."),

            SeedPersonality(2, "Иван III", "1440–1505", "ivan_iii.jpg", "Великий князь, при котором завершилось объединение земель и прекратилась зависимость от Орды.", "Иван III Васильевич родился 22 января 1440 года в Москве в семье великого князя Василия II Тёмного и княгини Марии Ярославны. Его детство и юность пришлись на междоусобную войну, в ходе которой отец был ослеплён и на время лишён престола. Уже в двенадцать лет Иван был обвенчан с дочерью тверского князя Марией Борисовной и стал соправителем отца; в пятнадцать лет совершил свой первый поход против татар, а к двадцати годам возглавил войско Московского княжества. После смерти Василия II в 1462 году Иван III занял московский престол и правил до 1505 года. За годы его правления территория государства увеличилась почти втрое: к Москве были присоединены Ярославское княжество (1463), Ростовское (1474), Новгородская республика (1478), Тверское княжество (1485), Вятская земля (1489) и другие территории. В 1480 году после стояния на реке Угре ордынское владычество над русскими землями было окончательно прекращено. При Иване III был принят Судебник 1497 года — первый общерусский свод законов, начала складываться приказная система управления, сформировалась государственная символика с двуглавым орлом. В 1472 году он женился на византийской царевне Софье Палеолог, что способствовало укреплению международного престижа Москвы. Умер 27 октября 1505 года."),
            SeedPersonality(2, "Василий III", "1479–1533", "vasily_iii.jpg", "Великий князь, завершивший объединение русских земель вокруг Москвы.", "Василий III Иванович родился 25 марта 1479 года в семье Ивана III и византийской царевны Софьи Палеолог. После смерти в 1490 году наследника престола Ивана Молодого, сына Ивана III от первого брака, развернулась борьба за престолонаследие, из которой Василий вышел победителем: он был назначен сначала великим князем Новгорода и Пскова, а затем стал соправителем отца. После смерти Ивана III в 1505 году беспрепятственно вступил на престол. Продолжая политику отца, Василий III окончательно ликвидировал систему удельных княжеств: в 1510 году был присоединён Псков, в 1513 году — Волоцкий удел, в 1521 году — Рязанское княжество, в 1522 году — Новгород-Северское. В ходе русско-литовской войны 1512–1522 годов в 1514 году был взят Смоленск. Для борьбы с Казанским ханством вблизи Казани была построена крепость Васильсурск. Первый брак с Соломонией Сабуровой оказался бездетным; в 1526 году Василий женился на княжне Елене Глинской, а в 1530 году у них родился сын — будущий царь Иван IV. Умер 4 декабря 1533 года, похоронен в Архангельском соборе Московского Кремля."),
            SeedPersonality(2, "Иван IV Грозный", "1530–1584", "ivan_grozny.jpg", "Первый венчанный на царство русский царь, при котором началось расширение государства на восток.", "Иван IV Васильевич родился 25 августа 1530 года в семье великого князя Василия III и Елены Глинской. После смерти отца в 1533 году и матери в 1538 году рос в обстановке боярских усобиц, которые тяжело отразились на его характере. В 1547 году в Успенском соборе Московского Кремля он венчался на царство, приняв титул «царя Всея Руси», что знаменовало начало Московского царства. В конце 1540-х — 1550-х годах при участии Избранной рады провёл серию реформ: созвал Земский собор (1549), издал Судебник (1550), усовершенствовал приказную систему, создал постоянное стрелецкое войско, созвал Стоглавый собор (1551). В 1552 году покорил Казанское ханство, в 1556 году — Астраханское, в 1557 году — Башкирию. В 1558 году начал Ливонскую войну за выход к Балтийскому морю, завершившуюся неудачей. В 1565 году учредил опричнину, сопровождавшуюся массовыми репрессиями и политическими заговорами (1567, 1569). Покровительствовал развитию культуры, церковному строительству и книгопечатанию: в 1564 году Иван Фёдоров выпустил «Апостол». Умер 18 марта 1584 года."),
            SeedPersonality(2, "Анастасия Романовна", "ок. 1530–1560", "anastasiya_romanovna.jpg", "Первая супруга Ивана IV, представительница рода Захарьиных-Юрьевых.", "Анастасия Романовна Захарьина-Юрьева родилась около 1531/32 года (по другим данным — 1533) в семье окольничего Романа Юрьевича Захарьина-Юрьева и Ульяны Ивановны. После смерти отца в 1543 году воспитывалась матерью. По свидетельству «Летописца начала царства», была выбрана в невесты лично царём Иваном IV; венчание провёл митрополит Московский Макарий в Успенском соборе 3 февраля 1547 года. Современники отмечали её добродетель, благочестие и благотворное влияние на мужа; князь Курбский писал, что она пользовалась любовью народа. Анастасия неоднократно совершала обетные паломничества, в том числе пешком в Троице-Сергиев монастырь, сопровождала мужа в поездках по монастырям. При её светлице существовала мастерская, где вышивались церковные пелены и покровы; сохранилось более полутора десятков произведений, связанных с её именем. Умерла 7 августа 1560 года в селе Коломенском. Смерть царицы современники связывали с отравлением, и Иван Грозный обвинил в «чародействе» своих бывших советников Сильвестра и Адашева. Род Захарьиных-Юрьевых, к которому она принадлежала, впоследствии стал основой династии Романовых."),
            SeedPersonality(2, "Ермак Тимофеевич", "ок. 1532–1585", "ermak.jpg", "Казачий атаман, возглавивший поход за Урал против Сибирского ханства.", "Ермак Тимофеевич родился около 1540 года (по другим данным — около 1532); сведения о его происхождении отрывочны и противоречивы. Существуют версии, что он был родом с берегов Камы, из Тотьмы, с Северной Двины или с Дона; точно установить его происхождение не удаётся. Длительное время его отряд волжских казаков действовал против татар в Поволжье. В начале 1580-х годов Строгановы пригласили его отряд для обороны своих владений в Пермском крае от набегов татар и вогулов. В конце августа — начале сентября 1582 года отряд Ермака численностью около 540 человек (с ними также шли 300 литовцев и немцев — военнопленных, служивших у Строгановых) начал поход в Сибирь. Казаки располагали огнестрельным оружием, что давало преимущество перед татарской конницей. Отряд разгромил силы сибирского хана Кучума в нескольких сражениях, а 23 октября (2 ноября) 1582 года в решающей битве под Чувашевом в устье реки Тобол нанёс поражение войску Маметкула, племянника Кучума. В октябре 1582 года Ермак занял столицу Сибирского ханства Кашлык. Погиб в ночь с 5 на 6 августа 1585 года в бою с татарами на реке Вагай. Поход Ермака положил начало присоединению Сибири к Русскому государству."),
            SeedPersonality(2, "Борис Годунов", "ок. 1551–1605", "boris_godunov.jpg", "Русский царь, правивший накануне Смутного времени.", "Борис Фёдорович Годунов родился около 1551/1552 года в семье боярина Фёдора Годунова. Годуновы вели происхождение от костромских бояр, служивших московским князьям, но не входивших в высшую знать. Возвышение Бориса началось после вступления в опричнину и сближения с Малютой Скуратовым; около 1570 года он женился на дочери Скуратова Марии. Несколько позже его сестра Ирина вышла замуж за царевича Фёдора Ивановича, что упрочило положение Годунова при дворе и обеспечило получение боярского чина в 1580 году. После смерти Ивана Грозного в 1584 году и вступления на престол Фёдора Иоанновича, неспособного самостоятельно управлять страной, Борис Годунов стал фактически единоличным правителем государства. Его правительство добилось учреждения патриаршества в 1589 году (первым патриархом стал митрополит Иов), провело перепись земель, издало указ об «урочных летах» (1597), ликвидировало «белые слободы» в городах, поощряло колонизацию Сибири и южных районов. Во внешней политике проявил себя как талантливый дипломат. После смерти царя Фёдора в 1598 году Земский собор избрал Бориса Годунова на царство. В его правление произошли трагические события: в 1591 году в Угличе погиб царевич Дмитрий, в 1601–1603 годах страну поразил Великий голод. В 1604 году началось вторжение Лжедмитрия I. Умер 13 апреля 1605 года."),
            SeedPersonality(2, "Минин Кузьма", "ок. 1570–1616", "minin.jpg", "Земский староста, один из организаторов Второго народного ополчения.", "Кузьма Минин (Кузьма Минич, фамилия точно не установлена; известна также как Сухорук) родился, по разным данным, в 1560-х или 1570-х годах. Происходил из семьи, принадлежавшей к средним слоям посада Нижнего Новгорода; сам был посадским человеком из «молодших», то есть небогатых. В августе — октябре 1611 года, во время польско-литовской интервенции, призывал к борьбе с интервентами. Предположительно 1 сентября 1611 года был избран земским старостой Нижнего Новгорода и обратился к горожанам с призывом «помочь Московскому государству», ссылаясь на слова увиденного во сне преподобного Сергия Радонежского. Его инициатива была поддержана посадскими людьми и духовенством; были собраны средства на формирование Второго ополчения, воеводой которого стал князь Дмитрий Пожарский, а Минин отвечал за казну. По пути к Москве он организовывал сбор чрезвычайного налога для выплаты жалованья ратным людям. В августе 1612 года участвовал в освобождении Москвы; 24 августа (3 сентября) командовал отрядом, удар которого во фланг войска гетмана Ходкевича во многом решил исход сражения. 12 июля 1613 года, на следующий день после венчания на царство Михаила Фёдоровича, был пожалован в думные дворяне — единственный в истории случай пожалования столь высокого чина человеку недворянского происхождения. Умер в 1616 году; гробница с 1962 года находится в Михаило-Архангельском соборе Нижегородского кремля."),
            SeedPersonality(2, "Дмитрий Пожарский", "1578–1642", "pozharsky.jpg", "Князь, возглавивший Второе народное ополчение вместе с Кузьмой Мининым.", "Дмитрий Михайлович Пожарский родился 1 ноября 1578 года в семье князя Михаила Фёдоровича Пожарского. Службу начал в чине «стряпчего с платьем»: в 1598 году подписал Утверждённую грамоту об избрании на царство Бориса Годунова. Участвовал в подавлении восстания Болотникова (1606–1607), разбил польско-литовский отряд в селе Высокое (1608/09), был воеводой в Зарайске (1610). Весной 1611 года участвовал в восстании москвичей против польско-литовского гарнизона и был тяжело ранен. Стал одним из организаторов и руководителей Второго ополчения 1611–1612 годов, его первым воеводой; рассылал грамоты в города с призывом присоединиться к ополчению, отправлял отряды для защиты и освобождения Ярославля, Суздаля, Углича и других городов. Весной 1612 года вошёл в состав Земского правительства. В августе 1612 года руководил ополчением при освобождении Москвы от польско-литовских войск. После избрания Михаила Романова на царство получил боярский чин и участвовал в государственном управлении. Умер 20 апреля 1642 года."),
            SeedPersonality(2, "Михаил Фёдорович Романов", "1596–1645", "mikhail_romanov.jpg", "Первый русский царь из династии Романовых, избранный Земским собором в 1613 году.", "Михаил Фёдорович Романов родился 12 (22) июля 1596 года в семье московских бояр Романовых. Его отец, Фёдор Никитич, был двоюродным братом последнего царя из династии Рюриковичей — Фёдора Ивановича; мать, Ксения Ивановна Шестова, происходила из костромских дворян. В 1601 году Романовы пали в немилость, и по приказу Бориса Годунова родителей Михаила насильственно постригли в монахи. Во время польской оккупации Москвы Михаил находился в плену в Кремле, откуда был освобождён в 1612 году Вторым ополчением. В январе 1613 года в Москве открылся Земский собор для избрания нового царя; по инициативе и под давлением «вольного казачества» одобрение получила кандидатура Михаила Фёдоровича. 21 февраля (3 марта) 1613 года произошло официальное избрание, а 11 (21) июля 1613 года он венчался на царство в Успенском соборе. В первые годы правления большинство государственных и внешнеполитических вопросов решал совместно с отцом, который в 1619 году стал патриархом Филаретом и фактически управлял государством до своей смерти в 1633 году. Главной задачей царствования было преодоление последствий Смуты: в 1617 году был заключён Столбовский мир со Швецией, в 1618 году — Деулинское перемирие с Речью Посполитой, в 1634 году — Поляновский мир. В годы его правления выросла система воеводского управления, получила развитие приказная система, началось составление новых писцовых книг, были введены полки иноземного строя. Умер 13 (23) июля 1645 года, похоронен в Архангельском соборе Московского Кремля."),
            SeedPersonality(2, "Софья Алексеевна", "1657–1704", "sofya_alekseevna.jpg", "Правительница-регент при малолетних Иване V и Петре I.", "Софья Алексеевна родилась в 1657 году в семье царя Алексея Михайловича и Марии Ильиничны Милославской, была шестым ребёнком из шестнадцати детей государя. Вопреки традициям воспитания царевен, получила образование под руководством известного учёного и поэта Симеона Полоцкого: освоила чтение и письмо, изучала греческий и латинский языки, историю и богословскую литературу. После смерти царя Фёдора Алексеевича в 1682 году в ходе борьбы между Милославскими и Нарышкиными и стрелецкого бунта добилась провозглашения Ивана V и Петра I соправителями при своём регентстве. В годы регентства (1682–1689) фактически управляла государством при участии князя Василия Голицына. В 1686 году заключила Вечный мир с Речью Посполитой, в 1687 и 1689 годах организовала Крымские походы, завершившиеся неудачей. В 1689 году была отстранена от власти Петром I и заключена в Новодевичий монастырь. Умерла 3 июля 1704 года."),

            SeedPersonality(3, "Пётр I", "1672–1725", "petr_1.jpg", "Последний царь всея Руси и первый Император Всероссийский, провёл масштабные реформы армии, управления и флота, основал Санкт-Петербург", "Родился 9 июня 1672 года в семье царя Алексея Михайловича и Натальи Нарышкиной. После смерти отца и правления брата Фёдора, в 1682 году был венчан на царство вместе со старшим братом Иваном V при регентстве сестры Софьи. Самостоятельно правил с 1689 года, отстранив Софью. В 1697–1698 годах совершил Великое посольство в Западную Европу под именем урядника Петра Михайлова, изучал кораблестроение, артиллерию и ремёсла. С 1700 года вёл Северную войну со Швецией, которая завершилась Ништадтским миром 1721 года и обеспечила России выход к Балтийскому морю. В 1703 году основал Санкт-Петербург, в 1712 году перенёс туда столицу. Учредил Сенат (1711), Синод (1721), ввёл Табель о рангах (1722) и подушную подать (1724), основал Академию наук (1724) и Кунсткамеру (1714). В 1721 году Сенат преподнёс ему титул «император Всероссийский», «Великий» и «Отец Отечества». Провёл реформу гражданского шрифта, которым с небольшими изменениями пользуются до сих пор. В 1722 году издал Указ о престолонаследии, согласно которому государь сам назначает преемника. Умер в 1725 году, не успев назвать наследника."),
            SeedPersonality(3, "Екатерина I", "1684–1727", "ekaterina_1.jpg", "Первая женщина на российском престоле, взошла после смерти Петра I при поддержке гвардии; при ней учреждён Верховный тайный совет", "Урождённая Марта Скавронская, происхождение точно не установлено: по одним сведениям дочь латышского крестьянина, по другим — шведского квартирмейстера. Юность провела в доме пастора Глюка в Мариенбурге, где была прачкой и кухаркой. В 1702 году после взятия Мариенбурга русскими войсками попала в плен, оказалась у А. Д. Меншикова, около 1703 года была замечена Петром I. Приняла православие под именем Екатерины Алексеевны, стала фактической женой царя, а в 1712 году обвенчалась с ним. Родила Петру одиннадцать детей, из которых выжили только дочери Анна и Елизавета. В 1724 году коронована как императрица. После смерти Петра I в 1725 году возведена на престол гвардией во главе с Меншиковым, который стал фактическим правителем. Государственными делами почти не занималась, передав управление Верховному тайному совету (1726). При ней открыта Академия наук, организована морская экспедиция Витуса Беринга, учреждён орден Святого Александра Невского. Скончалась в 1727 году, завещав престол 12-летнему Петру Алексеевичу."),
            SeedPersonality(3, "Елизавета Петровна", "1709–1762", "elizaveta_petrovna.jpg", "Императрица, дочь Петра I, при которой основаны Московский университет и Академия художеств, правила с 1741 по 1762 год", "Дочь Петра I и Екатерины I, родилась в 1709 году. Взошла на престол в 1741 году в результате дворцового переворота, свергнув малолетнего императора Иоанна VI и его регентов. Правила Российской империей с 1741 по 1762 год. При ней были основаны Московский университет (1755) и Академия художеств (1757). Период её правления отмечен возвращением к петровским традициям и активной внешней политикой. При Елизавете Петровне Россия участвовала в Семилетней войне против Пруссии. Скончалась в 1762 году, не оставив прямых наследников."),
            SeedPersonality(3, "Екатерина II", "1729–1796", "ekaterina_2.jpg", "Императрица, при которой значительно расширилась территория империи и проведены реформы управления и образования, правила с 1762 по 1796 год", "Урождённая принцесса София Августа Фредерика Ангальт-Цербстская, родилась в 1729 году в немецком Штеттине. В 1744 году прибыла в Россию как невеста великого князя Петра Фёдоровича, приняла православие с именем Екатерины Алексеевны и в 1745 году венчалась с ним. В 1754 году родила наследника, будущего императора Павла I. В 1762 году возглавила заговор гвардейцев и свергла Петра III, став императрицей. Правила с 1762 по 1796 год. В первые годы придерживалась политики «просвещённого абсолютизма», но после крестьянской войны под предводительством Емельяна Пугачёва (1773–1775) ужесточила режим. Провела губернскую реформу (1775). Вела победоносные войны с Турцией (1768–1774, 1787–1792) и Швецией (1788–1790). В годы её правления в состав России вошли Крым (1783), Северное Причерноморье, Прибалтика, восточные части Польши, Алеутские острова, созданы русские поселения на Аляске, взята под покровительство Восточная Грузия. Престиж России в Европе многократно вырос. Скончалась в 1796 году."),
            SeedPersonality(3, "Александр Суворов", "1730–1800", "suvorov.jpg", "Полководец, не проигравший ни одного крупного сражения; генералиссимус, известен переходом через Альпы", "Русский военачальник, генералиссимус, родился в 1730 году. В 12 лет был записан рядовым в лейб-гвардии Семёновский полк для получения офицерского чина. Участвовал в Семилетней войне, в подавлении сил Барской конфедерации, в Русско-турецких войнах второй половины XVIII века и в восстании Тадеуша Костюшко 1794 года. Особо отличился при взятии Измаила (1790). Свой опыт обучения и воспитания солдат, а также тактику боя изложил в труде «Наука побеждать». В 1799 году возглавил объединённую русско-австрийскую армию в Итальянском походе, затем совершил знаменитый Швейцарский поход — переход через Альпы, длившийся с 21 сентября по 8 октября 1799 года. Не проиграл ни одного крупного сражения. За Итальянский и Швейцарский походы удостоен звания генералиссимуса. Скончался в 1800 году."),
            SeedPersonality(3, "Михаил Кутузов", "1745–1813", "kutuzov.jpg", "Главнокомандующий русской армией в Отечественной войне 1812 года, первый полный кавалер ордена Святого Георгия", "Родился 16 сентября 1745 года в Санкт-Петербурге в семье генерал-поручика Иллариона Голенищева-Кутузова (часть исследователей со ссылкой на архивы указывает 1747 год). Окончил Артиллерийскую и инженерную дворянскую школу, выпущен в 1761 году инженер-прапорщиком, некоторое время преподавал там математику. Служил в Астраханском пехотном полку под командованием Суворова. Участвовал в Русско-турецкой войне 1768–1774 годов, отличился при Рябой Могиле, Ларге и Кагуле. В 1774 году тяжело ранен в голову в бою под Шумой (Крым), пуля прошла через висок, лишив левого глаза. Награждён орденом Святого Георгия 4-й степени. В 1788 году вновь тяжело ранен в голову под Очаковом. В 1790 году участвовал в штурме Измаила, командовал одной из колонн. В 1792 году назначен чрезвычайным и полномочным послом в Константинополе. В августе 1812 года назначен главнокомандующим всеми русскими армиями и ополчениями. Руководил Бородинским сражением, на совете в Филях принял решение оставить Москву ради сохранения армии. За изгнание Наполеона удостоен титула светлейшего князя Смоленского и ордена Святого Георгия 1-й степени, став первым полным Георгиевским кавалером. Умер в 1813 году в Бунцлау во время Заграничного похода."),
            SeedPersonality(3, "Александр Пушкин", "1799–1837", "pushkin.jpg", "Поэт, основоположник современного русского литературного языка, автор «Евгения Онегина» и «Капитанской дочки»", "Родился 6 июня 1799 года в Москве в дворянской семье. Отец Сергей Львович принадлежал к старинному дворянскому роду, мать Надежда Осиповна была внучкой Абрама Петровича Ганнибала, «арапа Петра Великого». Первоначальное образование получил дома. В 1811 году поступил в Царскосельский лицей, который окончил в 1817 году. Уже в 1814 году в журнале «Вестник Европы» опубликовано его первое стихотворение. В 1820 году вышла поэма «Руслан и Людмила». За политические стихи выслан из столицы, провёл «южную» ссылку в Кишинёве и Одессе, где начал работу над «Евгением Онегиным». В 1824 году выслан в Михайловское, где написал «Бориса Годунова». В 1826 году возвращён Николаем I из ссылки. В 1830 году провёл «Болдинскую осень», создав около 50 произведений. В 1831 году женился на Наталье Гончаровой. Автор «Евгения Онегина», «Капитанской дочки», «Бориса Годунова» и множества стихотворений. Погиб на дуэли с Дантесом 27 января 1837 года, скончался от ранения 10 февраля."),
            SeedPersonality(3, "Николай I", "1796–1855", "nikolay_1.jpg", "Император, правивший во время восстания декабристов; его правление завершилось Крымской войной", "Третий сын императора Павла I и императрицы Марии Фёдоровны. Вступил на престол в 1825 году после смерти брата Александра I и междуцарствия, начав правление с подавления восстания декабристов. Правление характеризовалось централизацией государственной власти и регламентацией всех сфер деятельности. В 1826 году создано Третье отделение Собственной Его Императорского Величества канцелярии для надзора за политической благонадёжностью подданных. В 1827 году опубликован цензурный устав, названный современниками «чугунным». В основе внутренней политики лежал принцип «самодержавие, православие, народность». При нём проведена кодификация законов (1832), построена первая железная дорога Петербург–Царское Село (1837). Русско-турецкая война (1828–1829) способствовала обретению независимости Греции (1830). Последние годы царствования омрачены военными неудачами в Крымской войне (1853–1856). Личность и деятельность императора вызывали противоречивые оценки — от восторженного почитания («рыцарь самодержавия») до категорического неприятия («жандарм Европы»). Скончался в 1855 году."),
            SeedPersonality(3, "Александр II", "1818–1881", "alexander_2.jpg", "Император, отменивший крепостное право в 1861 году, провёл судебную и военную реформы", "Сын Николая I, родился в 1818 году. Взошёл на престол в 1855 году во время Крымской войны. В 1861 году подписал Манифест об отмене крепостного права, освободив около 23 миллионов крестьян. Провёл ряд реформ: земскую (1864), судебную (1864), городскую (1870) и военную (1874), за что получил в историографии прозвание «Царь-Освободитель». Вёл активную внешнюю политику, завершил Кавказскую войну (1864), присоединил Среднюю Азию. Убит народовольцами 1 марта 1881 года в результате покушения."),
            SeedPersonality(3, "Сергей Витте", "1849–1915", "witte.jpg", "Государственный деятель, министр финансов и председатель Совета министров, провёл денежную реформу и способствовал индустриализации", "Родился в 1849 году в семье чиновника. Сделал карьеру на государственной службе, занимал пост министра путей сообщения, затем министра финансов (1892–1903). Провёл денежную реформу (1897), введя золотой стандарт, укрепивший российский рубль. Способствовал строительству Транссибирской магистрали и индустриализации страны. В 1905 году назначен председателем Совета министров, руководил подготовкой Манифеста 17 октября, даровавшего гражданские свободы и создавшего Государственную думу. Вышел в отставку в 1906 году. Скончался в 1915 году."),

            SeedPersonality(4, "Владимир Ленин", "1870–1924", "lenin.jpg", "Революционер, основатель партии большевиков, главный организатор Октябрьской революции 1917 года и первый председатель Совета народных комиссаров", "Родился 22 апреля 1870 года в Симбирске в семье инспектора народных училищ Ильи Ульянова. В 1887 году его старший брат Александр был казнён за участие в покушении на царя, что оказало на Владимира определяющее влияние. В том же году поступил в Казанский университет, но был исключён за участие в студенческом движении. В 1893 году переехал в Петербург, занимался публицистикой и социал-демократией. В 1895 году основал «Союз борьбы за освобождение рабочего класса», был арестован и сослан в Енисейскую губернию, где в 1898 году женился на Надежде Крупской. В эмиграции основал газету «Искра», был одним из организаторов II съезда РСДРП. После Февральской революции 1917 года вернулся в Россию и выступил с «Апрельскими тезисами». Возглавил Октябрьское вооружённое восстание, после которого на II Всероссийском съезде Советов был избран председателем Совета народных комиссаров. Руководил созданием Красной Армии, заключением Брестского мира, заменой политики «военного коммунизма» на новую экономическую политику (НЭП), основанием СССР в 1922 году. Скончался 21 января 1924 года в усадьбе Горки Московской области."),
            SeedPersonality(4, "Иосиф Сталин", "1878–1953", "stalin.jpg", "Руководитель СССР, генеральный секретарь ЦК ВКП(б), Верховный главнокомандующий в годы Великой Отечественной войны", "Родился 21 декабря 1879 года в грузинском городе Гори в семье сапожника Виссариона Джугашвили. Окончил Горийское духовное училище, учился в Тифлисской православной духовной семинарии, откуда был исключён в 1899 году за революционную деятельность. В 1901 году вступил в РСДРП, вёл подпольную работу, неоднократно подвергался арестам и ссылкам. В 1912 году заочно кооптирован в ЦК партии, участвовал в подготовке первого номера газеты «Правда». После Октябрьской революции вошёл в первое советское правительство как нарком по делам национальностей. В годы Гражданской войны был членом Реввоенсовета Республики, организовывал оборону Царицына и Петрограда. В 1922 году избран Генеральным секретарём ЦК, после смерти Ленина в 1924 году стал фактическим руководителем страны. Провёл форсированную индустриализацию и коллективизацию. С 1941 года — председатель Совнаркома, председатель Государственного Комитета Обороны и Верховный Главнокомандующий. Под его руководством СССР победил в Великой Отечественной войне. Скончался 5 марта 1953 года."),
            SeedPersonality(4, "Надежда Крупская", "1869–1939", "krupskaya.jpg", "Советский государственный и общественный деятель, жена и соратница Ленина, стоявшая у истоков советской системы народного образования", "Родилась 26 февраля 1869 года в Санкт-Петербурге в бедной дворянской семье. Окончила частную гимназию с золотой медалью, в 1889 году поступила на Бестужевские курсы. В 1890 году вступила в студенческий марксистский кружок, с 1891 года занималась с рабочими в воскресных школах. В 1894 году познакомилась с Владимиром Лениным, вместе с ним участвовала в создании петербургского «Союза борьбы за освобождение рабочего класса». В 1896 году арестована и выслана в село Шушенское, где в 1898 году вышла замуж за Ленина. В эмиграции работала секретарём партийных изданий, изучала педагогику, написала труд «Народное образование и демократия». После Октябрьской революции работала в Наркомате просвещения РСФСР, с 1929 года — заместитель наркома просвещения. Стояла у истоков пионерской организации и комсомола, занималась вопросами женского движения и просвещения народов страны. Скончалась 27 февраля 1939 года в Москве."),
            SeedPersonality(4, "Сергей Королёв", "1907–1966", "korolev.jpg", "Советский учёный и конструктор, основоположник практической космонавтики, главный конструктор ракетно-космической техники СССР", "Родился 12 января 1907 года в Житомире в семье преподавателя русской словесности. В школьные годы увлёкся авиацией, в 1923 году вступил в Общество друзей воздушного флота, сконструировал свой первый планер. В 1924 году поступил в Киевский политехнический институт, затем перевёлся в Московское высшее техническое училище имени Баумана. Будучи студентом, познакомился с трудами Циолковского и работами Цандера, после чего переключился на ракетостроение. В 1930-е годы возглавлял Группу изучения реактивного движения (ГИРД), стал одним из руководителей Реактивного научно-исследовательского института. В 1938 году был репрессирован, находился в заключении, работал в конструкторском бюро Туполева. После освобождения руководил разработкой баллистических ракет. Под его руководством был запущен первый искусственный спутник Земли (1957) и осуществлён первый полёт человека в космос (1961). Дважды Герой Социалистического Труда, академик АН СССР. Скончался 14 января 1966 года в Москве."),
            SeedPersonality(4, "Юрий Гагарин", "1934–1968", "gagarin.jpg", "Первый человек, совершивший полёт в космос; 12 апреля 1961 года выполнил орбитальный полёт на корабле «Восток-1»", "Родился 9 марта 1934 года в деревне Клушино Смоленской области в семье колхозников. Детство прошло в годы войны, семья пережила немецкую оккупацию. После освобождения района семья переехала в Гжатск. В 1949 году поступил в Люберецкое ремесленное училище, затем учился в Саратовском индустриальном техникуме, где в 1954 году записался в аэроклуб ДОСААФ. В 1955 году призван в армию и направлен в 1-е Чкаловское военное авиационное училище лётчиков в Оренбурге, которое окончил в 1957 году. Служил лётчиком-истребителем. В 1959 году отобран в группу кандидатов в космонавты. 12 апреля 1961 года совершил первый в истории человечества орбитальный космический полёт на корабле «Восток-1», длившийся 108 минут. После полёта стал всемирно известным, занимался общественной деятельностью и подготовкой космонавтов. Погиб 27 марта 1968 года в авиационной катастрофе во время тренировочного полёта."),
            SeedPersonality(4, "Валентина Терешкова", "род. 1937", "tereshkova.jpg", "Первая женщина-космонавт; в 1963 году совершила полёт на корабле «Восток-6», остаётся единственной женщиной, летавшей в космос в одиночку", "Родилась 6 марта 1937 года в деревне Большое Масленниково Ярославской области в рабоче-крестьянской семье. После гибели отца на советско-финляндской войне переехала с матерью в Ярославль. Окончила семь классов школы, вечернюю школу рабочей молодёжи и Ярославский заочный техникум лёгкой промышленности. Работала на шинном заводе и комбинате технических тканей. Увлеклась парашютным спортом в местном аэроклубе, выполнив более 90 прыжков. В 1962 году отобрана в группу кандидатов в космонавты из числа женщин. 16 июня 1963 года совершила полёт на корабле «Восток-6» с позывным «Чайка», длившийся почти трое суток, за которые корабль сделал 48 витков вокруг Земли. После полёта окончила Военно-воздушную инженерную академию имени Жуковского, работала в Центре подготовки космонавтов, стала кандидатом технических наук, профессором, генерал-майором авиации. Занималась политической и общественной деятельностью."),
            SeedPersonality(4, "Мстислав Ростропович", "1927–2007", "rostropovich.jpg", "Всемирно известный виолончелист и дирижёр, один из крупнейших музыкантов XX века", "Родился 27 марта 1927 года в Баку в семье известного виолончелиста Леопольда Ростроповича. С ранних лет проявил музыкальные способности: в четыре года начал заниматься на рояле, в десять — на виолончели. В годы войны семья переехала в Оренбург, затем в Москву. В 16 лет поступил в Московскую консерваторию, где учился у Дмитрия Шостаковича и Сергея Прокофьева. Первый виолончельный концерт дал в 1942 году, в 1945 году получил золотую медаль на Первом конкурсе молодых исполнителей СССР. Преподавал в Ленинградской и Московской консерваториях. Многочисленные произведения для виолончели были написаны специально для него Шостаковичем, Прокофьевым, Бриттеном, Шнитке и другими композиторами. С 1977 по 1994 год работал художественным руководителем и дирижёром Национального симфонического оркестра США в Вашингтоне. Был активным защитником прав человека и демократических свобод. Скончался 27 апреля 2007 года в Москве."),
            SeedPersonality(4, "Алексей Леонов", "1934–2019", "leonov.jpg", "Космонавт, первым в истории вышедший в открытый космос в 1965 году; участник советско-американской миссии «Союз — Аполлон»", "Родился 30 мая 1934 года в селе Листвянка Кемеровской области в многодетной семье. Окончил Военную авиационную школу первоначального обучения лётчиков в Кременчуге и Чугуевское военное авиационное училище лётчиков. В 1960 году зачислен в первый отряд советских космонавтов. 18 марта 1965 года совершил свой первый космический полёт в качестве второго пилота корабля «Восход-2» под командованием Павла Беляева. Во время этого полёта совершил первый в истории выход человека в открытый космос, продлившийся около 12 минут. При возвращении на корабль столкнулся с нештатной ситуацией: скафандр раздулся, и ему пришлось стравливать давление, чтобы вернуться в шлюз. В июле 1975 года участвовал в полёте по программе «Союз — Аполлон» и первой в истории стыковке космических кораблей СССР и США. С 1970 по 1991 год был заместителем начальника Центра подготовки космонавтов. Дважды Герой Советского Союза, кандидат технических наук, автор изобретений и научных трудов, а также художник. Скончался 11 октября 2019 года в Москве."),
            SeedPersonality(4, "Андрей Сахаров", "1921–1989", "sakharov.jpg", "Физик-теоретик, один из создателей советской водородной бомбы, впоследствии видный правозащитник и лауреат Нобелевской премии мира", "Родился 21 мая 1921 года в Москве в интеллигентной семье, отец преподавал физику. В 1938 году поступил на физический факультет Московского государственного университета, который окончил с отличием в 1942 году в эвакуации в Ашхабаде. Работал инженером-изобретателем на военном заводе в Ульяновске. В 1945 году поступил в аспирантуру Физического института АН СССР под руководством Игоря Тамма. С 1948 по 1968 год участвовал в разработке термоядерного оружия, вместе с Таммом сформулировал принципы управляемой термоядерной реакции. За участие в создании первой советской водородной бомбы (испытана в 1953 году) получил Сталинскую премию и звание Героя Социалистического Труда (трижды). С конца 1950-х годов выступал против испытаний ядерного оружия. В 1968 году опубликовал работу «Размышления о прогрессе, мирном сосуществовании и интеллектуальной свободе», после чего был отстранён от секретных работ. В 1975 году удостоен Нобелевской премии мира. В 1980 году за протест против ввода советских войск в Афганистан лишён всех наград и сослан в Горький. Возвращён из ссылки в 1986 году. В 1989 году избран народным депутатом СССР. Скончался 14 декабря 1989 года в Москве."),
            SeedPersonality(4, "Михаил Горбачёв", "1931–2022", "gorbachev.jpg", "Последний генеральный секретарь ЦК КПСС и первый президент СССР, инициатор перестройки и гласности, лауреат Нобелевской премии мира", "Родился 2 марта 1931 года в селе Привольное Ставропольского края в крестьянской семье. В 1955 году окончил юридический факультет Московского государственного университета, в 1967 году — заочно Ставропольский сельскохозяйственный институт. Сделал карьеру на комсомольской и партийной работе в Ставрополье, в 1970 году стал первым секретарём Ставропольского крайкома КПСС. С 1971 года — член ЦК КПСС, с 1980 года — член Политбюро. В марте 1985 года избран генеральным секретарём ЦК КПСС. Инициировал курс на перестройку, политику гласности и демократизацию, ослабление цензуры, развитие рыночных элементов в экономике. Во внешней политике проводил курс «нового мышления», способствовал окончанию холодной войны, выводу советских войск из Афганистана, объединению Германии. В 1990 году стал первым и единственным президентом СССР. В декабре 1991 года, после подписания Беловежских соглашений о создании СНГ и прекращении существования СССР, объявил об отставке. Скончался 30 августа 2022 года в Москве."),
            SeedPersonality(4, "Никита Хрущёв", "1894–1971", "khrushchev.jpg", "Советский партийный и государственный деятель, фактический руководитель СССР в 1953–1964 годах, выступил на XX съезде КПСС с докладом о культе личности Сталина, инициатор политики «оттепели»", "Родился в крестьянской семье в селе Калиновка Курской губернии. С юных лет работал слесарем на заводах и шахтах Донбасса. В 1918 году вступил в большевистскую партию, участвовал в Гражданской войне. В 1920-е годы вёл партийную работу на Украине, в 1930-е — в Московской парторганизации. С 1938 года — первый секретарь ЦК КП(б) Украины. С 1939 года — член Политбюро ЦК ВКП(б). В годы Великой Отечественной войны был членом военных советов ряда фронтов. В сентябре 1953 года избран первым секретарём ЦК КПСС. В феврале 1956 года на XX съезде выступил с закрытым докладом «О культе личности и его последствиях». С 1958 года одновременно возглавлял Совет министров СССР. Проводил массовое жилищное строительство, освоение целины, «кукурузную кампанию», административные реформы. Во внешней политике провозгласил курс на мирное сосуществование, но пережил Карибский кризис 1962 года. В октябре 1964 года отстранён от власти в результате внутрипартийного переворота, после чего находился на пенсии. Скончался в 1971 году в Москве."),
            SeedPersonality(4, "Леонид Брежнев", "1906–1982", "brezhnev.jpg", "Советский партийный и государственный деятель, генеральный секретарь ЦК КПСС в 1964–1982 годах, при нём военная мощь СССР достигла пика, а внешняя политика получила название «доктрины Брежнева»", "Родился в семье рабочего в Каменском (ныне Днепродзержинск) Екатеринославской губернии. В 1935 году окончил металлургический институт в Днепродзержинске, работал инженером. В 1931 году вступил в ВКП(б). В 1930-е годы на партийной работе в Днепропетровской области. С 1950 года — первый секретарь ЦК Компартии Молдавии. В 1952 году избран в Президиум ЦК КПСС. В 1954–1956 годах руководил освоением целинных земель в Казахстане. В 1960–1964 годах — председатель Президиума Верховного Совета СССР. В октябре 1964 года участвовал в смещении Хрущёва и занял пост первого секретаря ЦК КПСС (с 1966 года — генеральный секретарь). При нём введены войска в Чехословакию (1968) и Афганистан (1979), достигнут военный паритет с США. В последние годы тяжело болел. Скончался в 1982 году в Москве."),
            SeedPersonality(4, "Юрий Андропов", "1914–1984", "andropov.jpg", "Советский партийный и государственный деятель, генеральный секретарь ЦК КПСС в 1982–1984 годах, ранее председатель КГБ СССР (1967–1982)", "Родился в семье железнодорожного служащего на станции Нагутская Ставропольского края. В 1936 году окончил Рыбинский техникум водного транспорта, затем учился в Петрозаводском государственном университете. В 1939 году вступил в ВКП(б). В годы Великой Отечественной войны работал в комсомоле Карелии, участвовал в организации партизанского движения. В 1954–1957 годах — чрезвычайный и полномочный посол СССР в Венгрии, участвовал в урегулировании событий 1956 года. С 1962 года — секретарь ЦК КПСС. В 1967–1982 годах — председатель Комитета государственной безопасности СССР. В ноябре 1982 года после смерти Брежнева избран генеральным секретарём ЦК КПСС. Инициировал кампанию по укреплению дисциплины и борьбе с коррупцией, но из-за резкого ухудшения здоровья находился у власти менее полутора лет. Скончался в 1984 году в Москве."),
            SeedPersonality(4, "Константин Черненко", "1911–1985", "chernenko.jpg", "Советский партийный и государственный деятель, генеральный секретарь ЦК КПСС в 1984–1985 годах, представитель консервативного крыла брежневского окружения", "Родился в крестьянской семье в селе Большая Тесь Енисейской губернии. Работал батраком, служил в пограничных войсках. В 1931 году вступил в ВКП(б). В 1930-е годы на партийной и комсомольской работе в Красноярском крае. В 1945 году окончил Высшую партийную школу. С 1956 года работал в аппарате ЦК КПСС, с 1965 года — заведующий Общим отделом ЦК. С 1976 года — секретарь ЦК КПСС, с 1978 года — член Политбюро. Был близким помощником Брежнева, ведал документами и кадровыми вопросами. В феврале 1984 года после смерти Андропова избран генеральным секретарём ЦК КПСС, став самым пожилым (72 года) руководителем СССР при вступлении в должность. Из-за тяжёлой болезни фактически не мог полноценно управлять страной. Скончался в 1985 году в Москве, его смерть открыла путь к власти Горбачёву."),
            SeedPersonality(4, "Николай Рыжков", "1929–2024", "ryzhkov.jpg", "Советский государственный деятель, председатель Совета министров СССР в 1985–1991 годах, в период горбачёвской перестройки", "Родился в семье рабочего в городе Дзержинск Донецкой области. В 1959 году окончил Уральский политехнический институт. С 1950-х годов работал на Уральском машиностроительном заводе имени С. Орджоникидзе в Свердловске, прошёл путь от мастера до директора предприятия. В 1975 году назначен первым заместителем министра тяжёлого и транспортного машиностроения СССР, в 1979 году — первым заместителем председателя Госплана СССР. В 1982 году возглавил экономический отдел ЦК КПСС. В сентябре 1985 года назначен председателем Совета министров СССР. На этом посту столкнулся с нарастанием бюджетного дефицита, товарным голодом и забастовочным движением (шахтёрские забастовки 1989 года). В 1990 году предлагал программу перехода к регулируемой рыночной экономике, не получившую поддержки Верховного Совета. В январе 1991 года ушёл в отставку. В дальнейшем был депутатом Государственной думы. Скончался в 2024 году."),
            SeedPersonality(4, "Эдуард Шеварднадзе", "1928–2014", "shevardnadze.jpg", "Советский и грузинский государственный деятель, министр иностранных дел СССР в 1985–1990 годах, один из главных проводников «нового мышления» Горбачёва, позднее президент Грузии", "Родился в семье учителя в селе Мамати Ланчхутского района Грузинской ССР. В 1948 году вступил в ВКП(б). В 1950-е годы работал в комсомоле и органах внутренних дел Грузии. В 1965–1972 годах — министр внутренних дел Грузинской ССР, прославился борьбой с коррупцией и «теневым» рынком. В 1972 году избран первым секретарём ЦК Компартии Грузии. В июле 1985 года назначен министром иностранных дел СССР, не имея дипломатического опыта. Вёл переговоры с США по разоружению, подписал Договор о ликвидации ракет средней и меньшей дальности (1987), участвовал в урегулировании вывода войск из Афганистана и в процессе объединения Германии. В декабре 1990 года подал в отставку, предупредив о надвигающейся диктатуре. В 1992 году вернулся в Грузию, возглавил Государственный совет, в 1995–2003 годах — президент Грузии. Ушёл в отставку в ходе «революции роз» 2003 года. Скончался в 2014 году в Тбилиси."),
            SeedPersonality(4, "Александр Солженицын", "1918–2008", "solzhenitsyn.jpg", "Русский писатель, диссидент, лауреат Нобелевской премии по литературе 1970 года, автор «Архипелага ГУЛАГ», в 1974 году лишён гражданства и выслан из СССР", "Родился в Кисловодске в семье казака, погибшего на фронте до рождения сына. Окончил физико-математический факультет Ростовского университета и заочно Московский институт философии, литературы и истории. В годы Великой Отечественной войны командовал артиллерийской батареей, был награждён орденами. В феврале 1945 года арестован за критические высказывания о Сталине в письмах, приговорён к 8 годам лагерей и 3 годам ссылки. Освобождён в 1953 году, реабилитирован в 1956 году. В 1962 году с разрешения Хрущёва опубликована повесть «Один день Ивана Денисовича». После 1964 года его произведения печатались только за рубежом. В 1970 году удостоен Нобелевской премии по литературе. В 1973 году в Париже вышел «Архипелаг ГУЛАГ». В феврале 1974 года арестован, лишён гражданства и выслан из СССР. Жил в ФРГ, Швейцарии, с 1976 года — в США (Вермонт). Вернулся в Россию в 1994 году. Скончался в 2008 году в Москве."),

            SeedPersonality(5, "Борис Ельцин", "1931–2007", "yeltsin.jpg", "Первый президент Российской Федерации, избранный всенародным голосованием, занимал пост главы государства с 1991 по 1999 год", "Родился 1 февраля 1931 года в селе Бутка Талицкого района Свердловской области в крестьянской семье. В 1955 году окончил строительный факультет Уральского политехнического института по специальности «инженер-строитель». С 1955 по 1968 год работал мастером, прорабом, главным инженером стройуправления, начальником Свердловского домостроительного комбината. С 1968 года на партийной работе, в 1976–1985 годах — первый секретарь Свердловского обкома КПСС. В 1985 году переведён в Москву, возглавил Московский горком КПСС. В 1987 году ушёл из Политбюро, в 1990 году вышел из КПСС. 29 мая 1990 года избран Председателем Верховного Совета РСФСР. 12 июня 1991 года всенародным голосованием избран первым президентом России. В августе 1991 года возглавил сопротивление ГКЧП. В 1993 году противостояние с парламентом завершилось вооружённым разгоном Верховного Совета. 3 июля 1996 года избран на второй срок. 5 ноября 1996 года перенёс операцию аортокоронарного шунтирования. 31 декабря 1999 года добровольно объявил об отставке и передал полномочия председателю правительства Владимиру Путину. Скончался 23 апреля 2007 года в Москве."),
            SeedPersonality(5, "Владимир Путин", "род. 1952", "putin.jpg", "Президент Российской Федерации, занимавший высшие государственные должности в России в XXI веке", "Родился 7 октября 1952 года в Ленинграде. В 1975 году окончил юридический факультет Ленинградского государственного университета. По распределению направлен на работу в органы государственной безопасности, в 1985–1990 годах работал в ГДР. С 1990 года — помощник ректора ЛГУ по международным вопросам, затем советник председателя Ленинградского городского совета. С июня 1991 года — председатель Комитета по внешним связям мэрии Санкт-Петербурга. С 1996 года — заместитель управляющего делами Президента РФ. В 1998 году назначен директором ФСБ, одновременно с марта 1999 года — секретарь Совета Безопасности. С августа 1999 года — председатель Правительства. С 31 декабря 1999 года — исполняющий обязанности Президента. 26 марта 2000 года избран Президентом, вступил в должность 7 мая 2000 года. Переизбирался в 2004, 2012, 2018 и 2024 годах. В 2008–2012 годах занимал пост председателя Правительства. Кандидат экономических наук."),
            SeedPersonality(5, "Дмитрий Медведев", "род. 1965", "medvedev.jpg", "Государственный деятель, занимавший пост президента России в 2008–2012 годах и председателя правительства в 2012–2020 годах", "Родился 14 сентября 1965 года в Ленинграде. В 1987 году окончил юридический факультет Ленинградского государственного университета, в 1990 году — аспирантуру ЛГУ. Кандидат юридических наук, доцент. В 1990–1999 годах — на преподавательской работе в Санкт-Петербургском государственном университете, одновременно в 1990–1995 годах — советник председателя Ленинградского городского совета, эксперт Комитета по внешним связям мэрии Санкт-Петербурга. В 1999 году — заместитель руководителя Аппарата Правительства РФ. В 1999–2000 годах — заместитель руководителя Администрации Президента. С 2000 года — первый заместитель руководителя Администрации Президента. В 2000–2001 годах и с 2002 года — председатель Совета директоров ОАО «Газпром». С октября 2003 года — руководитель Администрации Президента. В ноябре 2005 года назначен первым заместителем председателя Правительства. 7 мая 2008 года вступил в должность Президента РФ. 8 мая 2012 года назначен председателем Правительства, занимал этот пост до 2020 года."),
            SeedPersonality(5, "Сергей Лавров", "род. 1950", "lavrov.jpg", "Российский дипломат, министр иностранных дел Российской Федерации с 2004 года", "Родился 21 марта 1950 года. В 1972 году окончил Московский государственный институт международных отношений МИД СССР. Начал дипломатическую деятельность в 1972 году в Посольстве СССР в Шри-Ланке. В 1976–1981 годах работал в Управлении международных экономических организаций МИД СССР. С 1981 по 1988 год — первый секретарь, советник и старший советник в Постоянном представительстве СССР при ООН. С 1988 по 1990 год — заместитель начальника Управления международных экономических отношений МИД СССР. В 1990–1992 годах — начальник Управления международных организаций МИД СССР. В 1992 году — директор Департамента международных организаций и глобальных проблем МИД России. В 1992–1994 годах — заместитель министра иностранных дел РФ. С 1994 по 2004 год — постоянный представитель РФ при ООН в Нью-Йорке. 9 марта 2004 года назначен министром иностранных дел РФ, переназначался в 2012, 2018, 2020 и 2024 годах. Имеет ранг Чрезвычайного и Полномочного Посла."),
            SeedPersonality(5, "Никита Михалков", "род. 1945", "mikhalkov.jpg", "Советский и российский кинорежиссёр, актёр и сценарист, лауреат международных кинематографических премий", "Родился 21 октября 1945 года в Москве в семье писателя Сергея Михалкова и поэтессы Натальи Кончаловской. В 1956–1959 годах учился в Центральной музыкальной школе при Московской консерватории. В 1963 году поступил в Театральное училище имени Щукина, откуда был отчислен, продолжил обучение на режиссёрском факультете ВГИКа, который окончил в 1971 году. Известность пришла после фильма «Я шагаю по Москве» (1963), где он сыграл главную роль. Дебютная режиссёрская работа — «Свой среди чужих, чужой среди своих» (1974). Среди его картин — «Раба любви», «Неоконченная пьеса для механического пианино», «Несколько дней из жизни Обломова», «Урга — территория любви», «Утомлённые солнцем» (получил «Оскар» за лучший иностранный фильм в 1995 году), «12». Председатель Союза кинематографистов России."),
            SeedPersonality(5, "Александр Овечкин", "род. 1985", "ovechkin.jpg", "Российский хоккеист, капитан клуба «Вашингтон Кэпиталз», один из самых результативных игроков в истории НХЛ", "Родился 17 сентября 1985 года в Москве. Воспитанник школы московского «Динамо». В Суперлиге дебютировал в 2001 году в возрасте 16 лет. На драфте НХЛ 2004 года выбран под общим первым номером клубом «Вашингтон Кэпиталз». В НХЛ выступает с 2005 года. Обладатель Кубка Стэнли 2018 года. Девять раз завоёвывал приз лучшему снайперу регулярного чемпионата НХЛ («Морис Ришар Трофи»). В сборной России дебютировал в 17 лет, стал самым молодым игроком и самым молодым автором заброшенной шайбы. Трёхкратный чемпион мира. В апреле 2025 года стал единоличным рекордсменом НХЛ по количеству заброшенных шайб в регулярных чемпионатах, опередив Уэйна Гретцки."),
            SeedPersonality(5, "Борис Немцов", "1959–2015", "nemtsov.jpg", "Один из лидеров демократических реформ 1990-х, первый губернатор Нижегородской области, вице-премьер России, в дальнейшем один из самых известных оппозиционных политиков", "Родился в 1959 году в Сочи. Окончил школу с золотой медалью, учился на радиофизическом факультете Горьковского университета, защитил кандидатскую диссертацию. В 1990 году избран народным депутатом РСФСР. В 1991 году назначен главой администрации Нижегородской области, в 1995 году выиграл губернаторские выборы, получив почти 60% голосов, став самым молодым губернатором в стране. В марте 1997 года перешёл в федеральное правительство, заняв пост первого вице-премьера и министра топлива и энергетики. После дефолта 1998 года ушёл в отставку. В 1999 году стал одним из лидеров «Союза правых сил», прошедшего в Госдуму. В 2003 году СПС не преодолел 5-процентный барьер. В последующие годы — один из лидеров внесистемной оппозиции, сопредседатель партии ПАРНАС. В 2013 году избран депутатом Ярославской областной думы. Убит 27 февраля 2015 года в центре Москвы."),
            SeedPersonality(5, "Егор Гайдар", "1956–2009", "gaidar.jpg", "Экономист и государственный деятель, идеолог и руководитель экономических реформ начала 1990-х, один из ключевых деятелей перехода к рыночной экономике", "Родился 16 марта 1956 года. После окончания экономического факультета МГУ продолжил учёбу в аспирантуре, в 1980 году стал кандидатом, в 1990 году — доктором экономических наук. До прихода в правительство работал в научных институтах, писал на экономические темы в журнале «Коммунист» и газете «Правда». В 1990-х годах занимал ключевые посты в правительстве России: был первым министром финансов РФ, первым заместителем, а затем исполняющим обязанности председателя правительства. Под его руководством в первой половине 1990-х годов проводились реформы, направленные на создание рыночной экономики, начался процесс приватизации. С 1994 по 2001 год возглавлял партию «Демократический выбор России», в 2001–2003 годах входил в руководство партии СПС. Скончался 16 декабря 2009 года."),
            SeedPersonality(5, "Анатолий Чубайс", "род. 1955", "chubais.jpg", "Государственный деятель и экономист, один из главных идеологов и руководителей экономических реформ 1990-х, включая приватизацию", "Родился 16 июня 1955 года в Борисове Белорусской ССР. В 1977 году окончил Ленинградский инженерно-экономический институт. Кандидат экономических наук. В 1990–1991 годах — заместитель, первый заместитель председателя исполкома Ленинградского городского Совета, главный экономический советник мэра Анатолия Собчака. С 1991 по 1994 год возглавлял Государственный комитет РФ по управлению государственным имуществом. В 1992–1994 годах одновременно занимал пост заместителя председателя правительства РФ. В 1994–1996 годах — первый заместитель председателя правительства. В 1996–1997 годах руководил Администрацией Президента. В 1997–1998 годах — первый заместитель председателя правительства, одновременно с марта по ноябрь 1997 года возглавлял Минфин. С 1998 по 2008 год — председатель правления РАО «ЕЭС России». В 2008–2020 годах возглавлял госкорпорацию «Роснано». В декабре 2020 года назначен специальным представителем Президента по связям с международными организациями, покинул пост в 2022 году."),
            SeedPersonality(5, "Валентина Матвиенко", "род. 1949", "matvienko.jpg", "Первая женщина в новейшей истории России, занимавшая пост губернатора Санкт-Петербурга; с 2011 года — председатель Совета Федерации", "Родилась 7 апреля 1949 года. Окончила Ленинградский химико-фармацевтический институт, Академию общественных наук, Дипломатическую академию МИД СССР. Чрезвычайный и Полномочный Посол. Занимала различные государственные должности, в 2003–2011 годах — губернатор Санкт-Петербурга. С августа 2011 года представляет в Совете Федерации исполнительный орган государственной власти Санкт-Петербурга, с сентября 2011 года — председатель Совета Федерации Федерального Собрания РФ. Герой Труда Российской Федерации, полный кавалер ордена «За заслуги перед Отечеством»."),
            SeedPersonality(5, "Сергей Шойгу", "род. 1955", "shoigu.jpg", "Основатель и многолетний руководитель МЧС России, в дальнейшем — министр обороны Российской Федерации", "Родился 21 мая 1955 года в городе Чадан Тувинской АССР. В 1977 году окончил Красноярский политехнический институт по специальности «инженер-строитель». Кандидат экономических наук. В 1977–1988 годах работал на строительных должностях в Красноярском крае и Туве. В 1988–1989 годах — второй секретарь Абаканского ГК КПСС. В 1990–1991 годах — заместитель председателя Государственного комитета РСФСР по архитектуре и строительству. В 1991 году возглавил Российский корпус спасателей, преобразованный в Государственный комитет по чрезвычайным ситуациям. В 1994–2012 годах — министр РФ по делам гражданской обороны, чрезвычайным ситуациям и ликвидации последствий стихийных бедствий. В 2012 году — губернатор Московской области. 6 ноября 2012 года назначен министром обороны РФ. Генерал армии, Герой Российской Федерации."),
            SeedPersonality(5, "Алексей Навальный", "1976–2024", "navalny.jpg", "Один из самых известных оппозиционных политиков и антикоррупционных активистов современной России, основатель Фонда борьбы с коррупцией", "Родился в 1976 году. Российский политический и общественный деятель, юрист, инвест-активист, бизнесмен. Позиционировал себя как главного оппонента руководству России во главе с Владимиром Путиным. Получил известность расследованиями о коррупции в России. Автор YouTube-каналов «Алексей Навальный» и «Навальный LIVE», общественно-политического блога. Основатель Фонда борьбы с коррупцией. В 2013 году участвовал в выборах мэра Москвы, заняв второе место. В 2021 году был арестован по обвинению в нарушении условий условного срока, позже приговорён к длительному сроку заключения. Скончался в феврале 2024 года в исправительной колонии."),
            SeedPersonality(5, "Владимир Жириновский", "1946–2022", "zhirinovsky.jpg", "Основатель и многолетний лидер ЛДПР, один из самых ярких и эпатажных политиков современной России, депутат Государственной думы всех созывов", "Родился 25 апреля 1946 года в Алма-Ате. Окончил Институт восточных языков при МГУ, затем вечернее отделение юридического факультета МГУ, который окончил с отличием. После службы в армии работал в Советском комитете защиты мира, затем в Инюрколлегии Министерства юстиции СССР, с 1983 года — в издательстве «Мир». В 1989 году стал членом инициативной группы по созданию Либерально-демократической партии Советского Союза. В 1990 году избран председателем ЛДПСС, преобразованной в ЛДПР. В 1991 году баллотировался на пост президента РСФСР, занял третье место. С 1993 года — депутат Госдумы, переизбирался семь раз. Шесть раз участвовал в президентских выборах. В 2000–2011 годах — вице-спикер Госдумы. Доктор философских наук, заслуженный юрист РФ. Скончался 6 апреля 2022 года после продолжительной болезни."),
        )
        personalities.forEach { person ->
            db.execSQL(
                """
                INSERT INTO personalities
